package ktanesolver.module.modded.regular.oddoneout;import java.util.*;import org.springframework.stereotype.Service;import ktanesolver.annotation.ModuleInfo;import ktanesolver.dto.ModuleCatalogDto;import ktanesolver.entity.*;import ktanesolver.enums.ModuleType;import ktanesolver.logic.*;
@Service @ModuleInfo(type=ModuleType.ODD_ONE_OUT,id="OddOneOutModule",name="Odd One Out",category=ModuleCatalogDto.ModuleCategory.MODDED_REGULAR,description="Track the five odd buttons and identify the uniquely frequent final button.",tags={"odd one out","stages","memory","buttons"})
public class OddOneOutSolver extends AbstractModuleSolver<OddOneOutInput,OddOneOutOutput>{@Override protected SolveResult<OddOneOutOutput>doSolve(RoundEntity round,BombEntity bomb,ModuleEntity module,OddOneOutInput input){if(input==null||input.oddPosition()<1||input.oddPosition()>6)return failure("Enter the odd button in reading order from 1 through 6");List<Integer>history=new ArrayList<>();Object saved=module.getState().get("oddOneOutHistory");if(saved instanceof List<?>list)for(Object x:list)if(x instanceof Number n)history.add(n.intValue());if(history.size()>=5)return failure("All five stage answers are already recorded; reset the module solver to start again");history.add(input.oddPosition());storeState(module,"oddOneOutHistory",List.copyOf(history));if(history.size()<5)return success(new OddOneOutOutput(history.size(),List.copyOf(history),null,"press "+input.oddPosition()),false);Map<Integer,Long>counts=new HashMap<>();for(int p=1;p<=6;p++)counts.put(p,(long)java.util.Collections.frequency(history,p));Map<Long,List<Integer>>by=new HashMap<>();counts.forEach((p,c)->by.computeIfAbsent(c,k->new ArrayList<>()).add(p));List<Integer>unique=by.values().stream().filter(x->x.size()==1).flatMap(Collection::stream).toList();if(unique.size()!=1)return failure("The five entered stage answers do not yield exactly one uniquely frequent position; check the recorded stages");int answer=unique.get(0);return success(new OddOneOutOutput(6,List.copyOf(history),answer,"press "+answer));}}
